  },
  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "动机、query→KV 映射、逐 head 概率与输出、输出投影轴和缓存身份均有实质定义，并明确区分已输出 token 与已提交 KV。GQA 论文的转换与质量结论限定于固定研究设置。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "GQA 不会把输出 head 数改成 Hkv，也不能把输出投影的输入宽度按 Hkv 缩小。"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "生成循环还要记录已提交的 KV 长度与已输出 token，不能把输出计数当作缓存长度。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "清楚区分模型映射、后端均匀分组限制、显式展开、TP 局部映射和浮点等价。非整除 TP 的头集合推导正确，NxD 两种策略及回退条件与所给固定文档一致。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "μ 覆盖全部 Hq 个 qhead，每个 h 只对应一个 μ(h)，且 0≤μ(h)<Hkv。"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "浮点逐位相同不能由实数等价推出。"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "分组加载、逐 query head 的在线统计、空块、末次消费和候选提交已有完整主线，merge 可由提供的 K-ALG-004 摘录恢复。但输入把 K 的通道误写为 dV，且无 head 轴的 vis 无法实现前文允许的 V(i,h)。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "输入：Q[M,Hq,dK]、已发布 Khist/Vhist[n,Hkv,dV]、候选新 Knew/Vnew[M,Hkv,dV]"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "C ← {j∈J | vis(i,j)}"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "K/V 的片上 tile 只有在所有读取它的 qhead 和查询行完成消费后才能覆盖。"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "容量、等宽投影 FLOPs、理想 decode 强度、TP 副本和 ring 发送量的主要推导及单位正确，也区分逻辑读取与 HBM 事务。但 attention FLOPs 的统一 P_pair 乘 Hq 需要各 head 可见对数相同的条件，正文尚未与允许的逐 head 可见集合协调；投影成本负对照也没有独立工作计数参考。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "F_attn≈2·Hq·(dK＋dV)·P_pair。"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "不能把逻辑比直接当成设备时间比。"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "全组实际存了 8 份 head 数据，而逻辑上只有 6 份，物理容量是逻辑的 8/6。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "历史长度、query 分块、Hkv、TP、展开后端、量化、桶和窗口变化均说明保留对象、成本变化与改选条件。没有把改变 Hkv 当作已有 checkpoint 的无损执行优化。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "资源溢出或 tile 过大时减小 query 块，而不是改变 μ"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "质量评估不通过时改回 GQA/MHA 或重新训练，不能只看速度快"
        }
      ]
    },
    "diagnosis": {
      "assessment": "partial",
      "reason": "竞争解释与干预实验具体，错误 head 映射确实进入 attention 并被检测。主要缺口是宣称检测投影成本错误的检查只比较两个手写表达式，没有让错误经过独立计数或实际投影机制；执行成功不能支持该项验证结论。",
      "evidence": [
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "两类负对照都必须由被测机制触发，不能只让测试复述一个常数。"
        },
        {
          "path": "knowledge/models/gqa-kv-heads.md",
          "quote": "侦测负对照包括：使用 h mod Hkv 的错误映射、把非整除 TP 直接按整数除法分配、以及把投影成本错误地按 Hkv 代替 Hq。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-MODEL-002-R1-001",
      "criterion": "algorithm",
      "evidence": "正文定义“每 head 的 key 和 value 维度分别为 dK、dV”，伪代码却声明“已发布 Khist/Vhist[n,Hkv,dV]、候选新 Knew/Vnew[M,Hkv,dV]”，随后执行“dot(Q[i,h],Kall[j,m])”。",
      "impact": "当 dK≠dV 时，按声明构造的 K 无法与 dK 维 Q 做点积，完整算法的输入合同与数学定义不一致。现有检查只使用 dK=dV=2，不能揭示这一错误。",
      "blocking": true,
      "required_revision": "分别声明 Khist[n,Hkv,dK]、Vhist[n,Hkv,dV]、Knew[M,Hkv,dK] 和 Vnew[M,Hkv,dV]，保持中间与输出向量维度一致。"
    },
    {
      "id": "K-MODEL-002-R1-002",
      "criterion": "algorithm",
      "evidence": "函数定义为“其可见 key 位置集合为 V(i,h)”，合法条件要求“每个 qhead 的 softmax 分母只对其可见 key 求和”；算法却只输入“可见谓词 vis(i,j)”并使用“C ← {j∈J | vis(i,j)}”。成本又使用“F_attn≈2·Hq·(dK＋dV)·P_pair”。",
      "impact": "同组两个 qhead 若分别只允许读取不同 key，共享 vis 无法表示这两个合法集合；不等数量的逐 head 可见对也不能直接使用一个未经限定的 P_pair 乘 Hq。",
      "blocking": true,
      "required_revision": "使算法使用 vis(i,h,j)，并将一般计算量按 head 的可见对数求和；或者明确把该算法及简化成本式限定于各 head 共享可见规则，并说明一般 V(i,h) 如何处理。"
    },
    {
      "id": "K-MODEL-002-R1-003",
      "criterion": "diagnosis",
      "evidence": "脚本仅执行“correct_proj = 4 * 1 * 4096 * 128 * (32 + 8)”和“wrong_proj = 4 * 1 * 4096 * 128 * (8 + 8)”，再检查“if correct_proj == wrong_proj:”。正文将其描述为“把投影成本错误地按 Hkv 代替 Hq”的侦测负对照。",
      "impact": "这只证明两个预写表达式不相等。即使正确公式本身错误，或者实际成本路径错误使用 Hkv，该检查仍会成功，不能验证 Q/K/V 与输出投影的轴和成本。",
      "blocking": true,
      "required_revision": "以四个投影的实际矩阵几何独立枚举乘加工作，核对推导公式；让错误的 Q 或输出投影 head 宽度进入同一计数路径并被参考拒绝。同步准确说明哪些容量项只是算术核算。"
    }
  ],
  "limitations": [
    "本次阅读对象为用户提供的冻结文本和执行记录；documents 中哈希按要求原样绑定，未独立从文件字节重算。",
    "S-FI 只有经过作者提炼的完整机制说明，没有可读原始文档或源码；不据此确认具体 API 或全部 GQA 组合。",
    "没有独立重跑脚本；所给 remote_bwrap 记录显示绑定脚本退出码为 0，但这仅支持该次 CPU 检查实际执行完成。",
    "CPU 标量模型不验证真实 GPU/Neuron 数值、片上同步、物理事务、collective、真实量化格式、模型质量或知识使用效果。",
    "提供了链接文本及其部分目标内容，未独立检查磁盘上的全部链接目标和 reader.html 是否可打开。"
  ],
  "checks": [
    {
      "script": "tools/check_k_model_002_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "以下均完整阅读用户提供的提取文本，范围为零基半开字符区间：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/models/gqa-kv-heads.md [0,13413)；knowledge/sources/S-GQA.md [0,1154)；S-HF-CACHE.md [0,827)；S-FI.md [0,1582)；S-KIVI.md [0,713)；S-NXDI.md [0,559)；knowledge/algorithms/kv-compression.md [0,5839)；knowledge/system-semantics/distributed-state-transfer.md [0,3216)；references/S-GQA/fulltext.txt [0,23837)；references/S-HF-CACHE/fulltext.txt [0,7977)；references/S-KIVI/fulltext.txt [0,44977)；references/S-NXDI/fulltext.txt [0,48117)。完整检查了所给 tools/check_k_model_002_full.py，从 import math 到 main() 入口，以及 actual_preflight 的输出、执行参数、脚本哈希和隔离范围。以下只阅读提供的摘录，不列入 documents：paged-kv-capacity.md [0,4000)、[8000,9075)、[12000,15425)；attention-io.md [0,4500)、[8000,12000)；mla.md [0,849)、[8000,15651)；memory-and-roofline.md [0,8500)；parallelism.md [0,8000)、[12000,12500)；quantization-contract.md [0,2105)、[8000,14395)；neuron-serving.md [4000,12500)；prefill-decode-state.md [0,4500)、[8000,12000)。未声称阅读这些摘录之外的原章、PDF 版面、图像或源码归档。",
  "test_assessment": "独立语义检查确认：grouped_attention 按 KV head 组织消费，dense_attention 按展开后的 query head 独立计算稳定整行 softmax，两者的数据流不同；固定分组断言还核对了连续 μ。错误 h mod Hkv 确实进入 grouped_attention，所给执行输出的最大差异为 0.1213680293714069，因此这个负对照有效检验了本章核心头映射。local_kv_sets 从全局 query 分片和 μ 计算集合，所得 ((0,1),(1,2),(3,4),(4,5)) 与人工推导一致；TP16 的 262144/131072 字节也正确。容量和有效位宽部分是固定算术核算。投影负对照只是两个手写表达式的不等比较，缺少独立参考，不能认可为机制检测。实际 attention 用例只有一个 query 行、三个 key、dK=dV=2，覆盖 MHA/MQA/均匀 GQA；没有执行在线 tile merge、空可见行、逐 head mask、不等 K/V 维度、偏置、分页或多步提交。脚本保留 visible 参数但 main 未使用它。loads 统计的是每次取得一对 K/V 向量的逻辑事件，不是标量字节或设备事务。max_delta 也未显式拒绝 NaN，因此不能把其容差检查推广到非有限输入。作者说明自己未运行检查与后续提供的实际预检记录可以并存；本审查仅确认所给记录的退出码和输出，不将未执行范围记为 PASS。"
}
